// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/// @title MultiRoundAirdrop - Distributes tokens across multiple rounds with Merkle verification
/// @notice Each round has a Merkle root. Users submit proof to claim their allocation.
/// @dev Uses standard Merkle proof verification pattern for gas-efficient airdrops
contract MultiRoundAirdrop is ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Round {
        bytes32 merkleRoot;
        uint256 totalAllocation;
        uint256 totalClaimed;
        uint64 startTime;
        uint64 endTime;
        bool active;
    }

    IERC20 public immutable token;
    address public admin;
    uint256 public roundCount;

    mapping(uint256 => Round) public rounds;
    // roundId => leaf hash => claimed
    mapping(uint256 => mapping(bytes32 => bool)) public leafClaimed;
    // user => roundId => amount claimed
    mapping(address => mapping(uint256 => uint256)) public userClaims;

    event RoundCreated(uint256 indexed roundId, bytes32 merkleRoot, uint256 totalAllocation);
    event Claimed(uint256 indexed roundId, address indexed user, uint256 amount);
    event AdminTransferred(address indexed oldAdmin, address indexed newAdmin);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor(address _token, address _admin) {
        require(_token != address(0), "Invalid token");
        require(_admin != address(0), "Invalid admin");
        token = IERC20(_token);
        admin = _admin;
    }

    /// @notice Create a new airdrop round
    /// @param merkleRoot The root of the Merkle tree for this round
    /// @param totalAllocation Total tokens allocated for this round
    /// @param startTime When claims open
    /// @param endTime When claims close
    function createRound(
        bytes32 merkleRoot,
        uint256 totalAllocation,
        uint64 startTime,
        uint64 endTime
    ) external onlyAdmin {
        require(merkleRoot != bytes32(0), "Invalid root");
        require(totalAllocation > 0, "Invalid allocation");
        require(endTime > startTime, "Invalid time range");
        require(startTime >= block.timestamp, "Start in past");

        token.safeTransferFrom(msg.sender, address(this), totalAllocation);

        uint256 roundId = roundCount++;
        rounds[roundId] = Round({
            merkleRoot: merkleRoot,
            totalAllocation: totalAllocation,
            totalClaimed: 0,
            startTime: startTime,
            endTime: endTime,
            active: true
        });

        emit RoundCreated(roundId, merkleRoot, totalAllocation);
    }

    /// @notice Claim tokens for a specific round
    /// @param roundId The round to claim from
    /// @param account The account that is entitled to claim
    /// @param amount The amount entitled
    /// @param proof The Merkle proof
    function claim(
        uint256 roundId,
        address account,
        uint256 amount,
        bytes32[] calldata proof
    ) external nonReentrant {
        Round storage round = rounds[roundId];
        require(round.active, "Round not active");
        require(block.timestamp >= round.startTime, "Not started");
        require(block.timestamp <= round.endTime, "Ended");
        require(amount > 0, "Zero amount");

        // Compute leaf from account and amount
        bytes32 leaf = _computeLeaf(account, amount);
        require(!leafClaimed[roundId][leaf], "Already claimed");

        // Verify Merkle proof
        require(_verifyProof(proof, round.merkleRoot, leaf), "Invalid proof");

        // Mark as claimed
        leafClaimed[roundId][leaf] = true;
        round.totalClaimed += amount;
        userClaims[account][roundId] += amount;

        require(round.totalClaimed <= round.totalAllocation, "Exceeds allocation");

        // Transfer tokens
        token.safeTransfer(account, amount);

        emit Claimed(roundId, account, amount);
    }

    /// @notice Batch claim across multiple rounds
    /// @param roundIds Array of round IDs
    /// @param accounts Array of accounts
    /// @param amounts Array of amounts
    /// @param proofs Array of Merkle proofs
    function batchClaim(
        uint256[] calldata roundIds,
        address[] calldata accounts,
        uint256[] calldata amounts,
        bytes32[][] calldata proofs
    ) external nonReentrant {
        require(
            roundIds.length == accounts.length &&
            accounts.length == amounts.length &&
            amounts.length == proofs.length,
            "Length mismatch"
        );
        require(roundIds.length <= 20, "Too many claims");

        for (uint256 i = 0; i < roundIds.length; i++) {
            _processClaim(roundIds[i], accounts[i], amounts[i], proofs[i]);
        }
    }

    /// @notice Deactivate a round (admin only)
    function deactivateRound(uint256 roundId) external onlyAdmin {
        require(rounds[roundId].active, "Already inactive");
        rounds[roundId].active = false;
    }

    /// @notice Recover unclaimed tokens after round ends
    function recoverTokens(uint256 roundId) external onlyAdmin {
        Round storage round = rounds[roundId];
        require(!round.active || block.timestamp > round.endTime, "Round still active");
        uint256 unclaimed = round.totalAllocation - round.totalClaimed;
        require(unclaimed > 0, "Nothing to recover");
        round.totalClaimed = round.totalAllocation; // Prevent double recovery
        token.safeTransfer(admin, unclaimed);
    }

    function transferAdmin(address newAdmin) external onlyAdmin {
        require(newAdmin != address(0), "Invalid admin");
        emit AdminTransferred(admin, newAdmin);
        admin = newAdmin;
    }

    /// @dev Compute the leaf hash for Merkle tree
    /// @notice Uses encodePacked for gas efficiency - leaf nodes are always
    /// (address, uint256) pairs which have fixed sizes, preventing collisions
    function _computeLeaf(address account, uint256 amount) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(account, amount));
    }

    /// @dev Standard Merkle proof verification
    function _verifyProof(
        bytes32[] calldata proof,
        bytes32 root,
        bytes32 leaf
    ) internal pure returns (bool) {
        bytes32 computedHash = leaf;
        for (uint256 i = 0; i < proof.length; i++) {
            computedHash = _hashPair(computedHash, proof[i]);
        }
        return computedHash == root;
    }

    /// @dev Hash a pair of nodes - uses sorted concatenation to allow
    /// proof verification without tracking left/right positioning
    function _hashPair(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        if (a < b) {
            return keccak256(abi.encodePacked(a, b));
        } else {
            return keccak256(abi.encodePacked(b, a));
        }
    }

    /// @dev Internal claim processing for batch operations
    function _processClaim(
        uint256 roundId,
        address account,
        uint256 amount,
        bytes32[] calldata proof
    ) internal {
        Round storage round = rounds[roundId];
        require(round.active, "Round not active");
        require(block.timestamp >= round.startTime, "Not started");
        require(block.timestamp <= round.endTime, "Ended");
        require(amount > 0, "Zero amount");

        bytes32 leaf = _computeLeaf(account, amount);
        require(!leafClaimed[roundId][leaf], "Already claimed");
        require(_verifyProof(proof, round.merkleRoot, leaf), "Invalid proof");

        leafClaimed[roundId][leaf] = true;
        round.totalClaimed += amount;
        userClaims[account][roundId] += amount;

        require(round.totalClaimed <= round.totalAllocation, "Exceeds allocation");

        token.safeTransfer(account, amount);

        emit Claimed(roundId, account, amount);
    }
}
